sparql_tries.sparql:
SELECT DISTINCT ?campno WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campno ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mn .
  FILTER(UCASE(STR(?mn)) IN ("HYUNDAI","KIA","GENESIS"))
} ORDER BY ?campno

SELECT DISTINCT ?campno ?date WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campno ;
     rc:reportReceivedDate ?date ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name "PALISADE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(YEAR(?date) = 2024)
} ORDER BY ?date ?campno

SELECT DISTINCT ?modelName ?makeName WHERE {
  ?c rc:affectsComponent ?comp .
  ?comp rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?c rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name ?modelName .
  OPTIONAL { ?m rc:ofMake ?mk . ?mk rc:name ?makeName }
} ORDER BY ?makeName ?modelName

SELECT ?campaignNumber (COUNT(DISTINCT ?makeName) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes) WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI","KIA","GENESIS"))
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?n .
  FILTER(?n IN ("HYUNDAI","KIA","GENESIS"))
  FILTER(YEAR(?d) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?r) AS ?n) WHERE {
  ?mk rc:name "GENESIS" .
  ?m rc:ofMake ?mk .
  ?v rc:ofModel ?m .
  ?r rc:affects ?v ;
     rc:affectsComponent ?c .
  ?c skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?up }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?n)

SELECT (COUNT(DISTINCT ?yr) AS ?count) WHERE {
  ?c a rc:RecallCampaign ; rc:affects ?v .
  ?v rc:ofModel ?m ; rc:modelYear ?yr .
  ?m rc:name "SONATA" ; rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
}

SELECT DISTINCT ?campno WHERE {
  ?r a rc:RecallCampaign ; rc:campaignNumber ?campno .
  { ?r rc:defectSummary ?t } UNION { ?r rc:consequenceSummary ?t } UNION { ?r rc:rootCause ?t }
  FILTER(REGEX(?t, "hydrogen", "i"))
} ORDER BY ?campno

SELECT DISTINCT ?campno WHERE {
  ?r a rc:RecallCampaign ; rc:campaignNumber ?campno .
  OPTIONAL { ?r rc:affectsComponent ?c . ?c rc:name ?cn }
  OPTIONAL { ?r rc:defectSummary ?d }
  FILTER (regex(?cn, "ICCU|INTEGRATED CHARGING", "i") || regex(?d, "ICCU|integrated charging control", "i"))
} ORDER BY ?campno

SELECT DISTINCT ?campno WHERE {
  ?c a rc:RecallCampaign ; rc:campaignNumber ?campno .
  { ?c rc:defectSummary ?t } UNION { ?c rc:rootCause ?t } UNION { ?c rc:consequenceSummary ?t }
  FILTER(REGEX(?t, "(water|moisture)", "i") && REGEX(?t, "(tow|trailer|hitch)", "i") && REGEX(?t, "(module|control unit)", "i"))
} ORDER BY ?campno
